/**
 * A fingerprint result containing hash data and duration.
 */
public struct FingerprintData {
    /**
     * Raw hash values.
     */
    public var hashes: [UInt32]
    /**
     * Duration of the audio in milliseconds.
     */
    public var durationMs: UInt32

    /// Default memberwise initializers are never public by default, so we
    /// declare one manually.
    public init(
        /* 
         * Raw hash values.
         */ hashes: [UInt32],
        /* 
            * Duration of the audio in milliseconds.
            */ durationMs: UInt32
    ) {
        self.hashes = hashes
        self.durationMs = durationMs
    }
}

extension FingerprintData: Equatable, Hashable {
    public static func == (lhs: FingerprintData, rhs: FingerprintData) -> Bool {
        if lhs.hashes != rhs.hashes {
            return false
        }
        if lhs.durationMs != rhs.durationMs {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(hashes)
        hasher.combine(durationMs)
    }
}

