/**
 * Compare two fingerprint hash arrays without drift compensation.
 *
 * # Arguments
 * * `hashes1` - First fingerprint hash array.
 * * `hashes2` - Second fingerprint hash array.
 *
 * # Returns
 * Similarity score between 0.0 (completely different) and 1.0 (identical).
 */
public func compareHashes(hashes1: [UInt32], hashes2: [UInt32]) -> Float {
    return try! FfiConverterFloat.lift(try! rustCall {
        uniffi_fingerprint_uniffi_fn_func_compare_hashes(
            FfiConverterSequenceUInt32.lower(hashes1),
            FfiConverterSequenceUInt32.lower(hashes2), $0
        )
    })
}

/**
 * Compare two fingerprint hash arrays with drift compensation.
 *
 * This is the unified comparison function for all platforms.
 *
 * # Arguments
 * * `hashes1` - First fingerprint hash array.
 * * `hashes2` - Second fingerprint hash array.
 * * `max_drift` - Maximum number of hash positions to shift for alignment (0 = no drift).
 *
 * # Returns
 * Similarity score between 0.0 (completely different) and 1.0 (identical).
 */
public func compareHashesWithDrift(hashes1: [UInt32], hashes2: [UInt32], maxDrift: UInt32) -> Float {
    return try! FfiConverterFloat.lift(try! rustCall {
        uniffi_fingerprint_uniffi_fn_func_compare_hashes_with_drift(
            FfiConverterSequenceUInt32.lower(hashes1),
            FfiConverterSequenceUInt32.lower(hashes2),
            FfiConverterUInt32.lower(maxDrift), $0
        )
    })
}

