 * * `hashes` - Fingerprint hash values.
 * * `duration_ms` - Duration in milliseconds.
 *
 * # Returns
 * Serialized fingerprint bytes.
 */
public func fingerprintToBytes(hashes: [UInt32], durationMs: UInt32) -> Data {
    return try! FfiConverterData.lift(try! rustCall {
        uniffi_fingerprint_uniffi_fn_func_fingerprint_to_bytes(
            FfiConverterSequenceUInt32.lower(hashes),
            FfiConverterUInt32.lower(durationMs), $0
        )
